{"task": "Find log lines containing a Java exception stack trace frame", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, 'at [a-zA-Z0-9_.$]+\\([A-Za-z0-9_.]+\\.java:[0-9]+\\)')"}
{"task": "Find log lines containing a Python traceback frame", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, 'File \"[^\"]+\\.py\", line [0-9]+')"}
{"task": "Count stack-trace lines per service, distinguishing Java and Python frames", "sql": "SELECT service, SUM(CASE WHEN regexp_like(message, 'at [a-zA-Z0-9_.$]+\\([A-Za-z0-9_.]+\\.java:[0-9]+\\)') THEN 1 ELSE 0 END) AS java_frames, SUM(CASE WHEN regexp_like(message, 'File \"[^\"]+\\.py\", line [0-9]+') THEN 1 ELSE 0 END) AS python_frames FROM logs GROUP BY service"}
{"task": "List error-level logs that contain any kind of stack trace line from either language", "sql": "SELECT ts, service, message FROM logs WHERE level = 'ERROR' AND regexp_like(message, 'at [a-zA-Z0-9_.$]+\\([A-Za-z0-9_.]+\\.java:[0-9]+\\)|File \"[^\"]+\\.py\", line [0-9]+')"}
{"task": "Find Java stack traces that mention a specific exception class name pattern", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '[A-Za-z0-9_.]*Exception(?!\\w)') AND regexp_like(message, 'at [a-zA-Z0-9_.$]+\\([A-Za-z0-9_.]+\\.java:[0-9]+\\)')"}
{"task": "Find Python tracebacks that raised a specific error type at the final line", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '^[A-Za-z0-9_.]+Error: .+', 'm')"}
{"task": "Tag each log row with a stack-trace category using a CASE expression based on regexp_like matches", "sql": "SELECT ts, service, CASE WHEN regexp_like(message, 'at [a-zA-Z0-9_.$]+\\([A-Za-z0-9_.]+\\.java:[0-9]+\\)') THEN 'java_trace' WHEN regexp_like(message, 'File \"[^\"]+\\.py\", line [0-9]+') THEN 'python_trace' ELSE 'other' END AS trace_type FROM logs"}
{"task": "Find stack-trace lines referencing third-party or framework packages like org.springframework or com.google", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, 'at (org\\.springframework|com\\.google|org\\.apache)\\.[A-Za-z0-9_.]+\\([A-Za-z0-9_.]+\\.java:[0-9]+\\)')"}
{"task": "Find Python traceback lines that occur inside site-packages or virtualenv dependency code rather than application code", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, 'File \"[^\"]*(site-packages|venv)[^\"]*\\.py\", line [0-9]+')"}
{"task": "Get daily counts of distinct services emitting stack traces in the last 7 days", "sql": "SELECT CAST(ts AS DATE) AS day, COUNT(DISTINCT service) AS services_with_traces FROM logs WHERE ts >= now() - INTERVAL '7 days' AND regexp_like(message, 'at [a-zA-Z0-9_.$]+\\([A-Za-z0-9_.]+\\.java:[0-9]+\\)|Traceback \\(most recent call last\\)') GROUP BY day ORDER BY day"}

